    evidence_strength_confidence: answers.evidence_strength.confidence,

    evidence_quality: answers.evidence_quality.score,
    evidence_quality_confidence: answers.evidence_quality.confidence,

    contradictory_evidence: answers.contradictory_evidence.noul,

    jev_response: $json.result,

    jev_model: jev.model,
    jev_usage: jev.usage
  }
};

const result = $json;

const response = {
  request_id: result.id,
  question: result.question,
  proposition: result.research.normalized_proposition,

  prediction: Number(result.prediction),
  probability: Number(result.probability),

  evidence_strength: Number(result.evidence_strength),
  evidence_quality: Number(result.evidence_quality),

  contradictory_evidence: Number(
    result.jev_response.result.answers.contradictory_evidence.noul
  ),

  completed_at: result.completed_at,

  research: result.research
};

if (result.include_sources) {
  response.sources = result.sources || [];
}

return {
  json: response
};

