const forecast = $('Build Final Response').item.json;
const explanation = $json.content?.parts?.[0]?.text || '';

const probability = Number(forecast.probability);
const probabilityPercent = Math.round(probability * 100);

function extractSection(text, startPatterns, endPatterns) {
  let start = -1;

  for (const pattern of startPatterns) {
    const match = text.match(pattern);

    if (match) {
      start = match.index + match[0].length;
      break;
    }
  }

  if (start === -1) return '';

  let end = text.length;

  for (const pattern of endPatterns) {
    const remaining = text.slice(start);
    const match = remaining.match(pattern);

    if (match) {
      end = Math.min(end, start + match.index);
    }
  }

  return text.slice(start, end).trim();
}

function cleanText(text) {
  return text
    .replace(/\*\*/g, '')
    .replace(/^\s*\d+\.\s*/gm, '')
    .trim();
}

// Common Jev section headings.
// Gemini may return these with or without numbering and
// with or without "The".
const jevEvidenceStrengthHeading =
  /(?:\d+\.\s*)?(?:The\s+)?Jev Evidence-Strength Score\s*:?\s*/i;

const jevEvidenceQualityHeading =
  /(?:\d+\.\s*)?(?:The\s+)?Jev Evidence-Quality Score\s*:?\s*/i;

const contradictoryEvidenceNoulHeading =
  /(?:\d+\.\s*)?(?:The\s+)?Contradictory-Evidence Noul Value\s*:?\s*/i;

const jevScoresHeading =
  /(?:\d+\.\s*)?(?:The\s+)?Jev Scores\s*:?\s*/i;

const supportingEvidence = cleanText(
  extractSection(
    explanation,
    [/Main Supporting Evidence\s*:?\s*/i],
    [
      /Main Contradictory Evidence\s*:?\s*/i,
      /Important Uncertainties and Limitations\s*:?\s*/i,
      jevScoresHeading,
      jevEvidenceStrengthHeading,
      jevEvidenceQualityHeading,
      contradictoryEvidenceNoulHeading
    ]
  )
);

const contradictoryEvidence = cleanText(
  extractSection(
    explanation,
    [/Main Contradictory Evidence\s*:?\s*/i],
    [
      /Important Uncertainties and Limitations\s*:?\s*/i,
      jevScoresHeading,
      jevEvidenceStrengthHeading,
      jevEvidenceQualityHeading,
      contradictoryEvidenceNoulHeading
    ]
  )
);

const uncertainties = cleanText(
  extractSection(
    explanation,
    [/Important Uncertainties and Limitations\s*:?\s*/i],
    [
      jevScoresHeading,
      jevEvidenceStrengthHeading,
      jevEvidenceQualityHeading,
      contradictoryEvidenceNoulHeading,
      /EVIDENCE QUALITY\s*:?\s*/i
    ]
  )
);

let output = `EVALUATED PROPOSITION:

${forecast.proposition}

FORECAST:

${probabilityPercent}% probability

SUPPORTING EVIDENCE:

${supportingEvidence || 'No supporting evidence was identified.'}

CONTRADICTORY EVIDENCE:

${contradictoryEvidence || 'No contradictory evidence was identified.'}

UNCERTAINTIES:

${uncertainties || 'No additional uncertainties were identified.'}

EVIDENCE QUALITY:

Strength: ${Number(forecast.evidence_strength).toFixed(2)} / 4
Quality: ${Number(forecast.evidence_quality).toFixed(2)} / 4
Contradictory Evidence: ${Number(forecast.contradictory_evidence).toFixed(2)} / 1`;

if (forecast.sources && forecast.sources.length > 0) {
  output += `

SOURCES:
`;

  for (const source of forecast.sources) {
    const title = source.title || source.source_title || 'Source';
    const url = source.url || '';

    output += `\n• ${title}`;

    if (url) {
      output += `\n  ${url}`;
    }
  }
}

return {
  json: {
    output
  }
};

const research = $json.output;

return {
  json: {
    ...research,
    research_sufficient: research.research_sufficient === true,
    research_gap: research.research_gap || ''
  }
};

