const text = $json.content?.parts?.[0]?.text || '';

const supportingEvidence = [];
const contradictingEvidence = [];

function parseEvidenceBlock(block) {
  const results = [];

  const items = block
    .split(/\n(?=-\s*Claim:)/)
    .map(item => item.trim())
    .filter(Boolean);

  for (const item of items) {
    const claimMatch = item.match(
      /-\s*Claim:\s*(.*?)(?=\n\s*Source:|\n\s*URL:|\n\s*Date:|\n\s*Relevance:|$)/s
    );

    const sourceMatch = item.match(
      /Source:\s*(.*?)(?=\n\s*URL:|\n\s*Date:|\n\s*Relevance:|$)/s
    );

    const urlMatch = item.match(
      /URL:\s*(https?:\/\/[^\s]+)/i
    );

    const dateMatch = item.match(
      /Date:\s*(.*?)(?=\n\s*Relevance:|$)/s
    );

    const relevanceMatch = item.match(
      /Relevance:\s*(.*)$/s
    );

    const claim = claimMatch?.[1]?.trim() || '';
    const source_title = sourceMatch?.[1]?.trim() || '';
    const source_url = urlMatch?.[1]?.trim() || '';
    const publication_date = dateMatch?.[1]?.trim() || '';
    const relevance = relevanceMatch?.[1]?.trim() || '';

    // Only accept evidence with a claim and a real URL.
    if (claim && source_url) {
      results.push({
        claim,
        source_title,
        source_url,
        publication_date,
        relevance
      });
    }
  }

  return results;
}

const supportingMatch = text.match(
  /SUPPORTING EVIDENCE:\s*([\s\S]*?)(?=\n\s*CONTRADICTING EVIDENCE:|$)/i
);

const contradictingMatch = text.match(
  /CONTRADICTING EVIDENCE:\s*([\s\S]*)$/i
);

if (supportingMatch) {
  supportingEvidence.push(
    ...parseEvidenceBlock(supportingMatch[1])
  );
}

if (contradictingMatch) {
  contradictingEvidence.push(
    ...parseEvidenceBlock(contradictingMatch[1])
  );
}

return {
  json: {
    supporting_evidence: supportingEvidence,
    contradicting_evidence: contradictingEvidence
  }
};

const original = $('Check Research Sufficiency').item.json;
const gemini = $json;

function normalizeEvidence(evidence) {
  return {
    claim: evidence.claim || evidence.factual_claim || '',
    source_title: evidence.source_title || evidence.source || '',
    source_url: evidence.source_url || evidence.url || '',
    publication_date: evidence.publication_date || '',
    relevance: evidence.relevance || evidence.relevant || ''
  };
}

const originalSupporting =
  (original.supporting_evidence || []).map(normalizeEvidence);

const originalContradicting =
  (original.contradicting_evidence || []).map(normalizeEvidence);

const geminiSupporting =
  (gemini.supporting_evidence || []).map(normalizeEvidence);

const geminiContradicting =
  (gemini.contradicting_evidence || []).map(normalizeEvidence);

const supporting_evidence = [
  ...originalSupporting,
  ...geminiSupporting
];

const contradicting_evidence = [
  ...originalContradicting,
  ...geminiContradicting
];

const sources_used = [
  ...(original.sources_used || []).map(source => ({
    title: source.title || source.source_title || '',
    url: source.url || source.source_url || '',
    publication_date: source.publication_date || ''
  })),

  ...[...geminiSupporting, ...geminiContradicting]
    .filter(e => e.source_url)
    .map(e => ({
      title: e.source_title,
      url: e.source_url,
      publication_date: e.publication_date
    }))
];

// Determine whether the combined research actually contains
// meaningful source-backed evidence.
const hasSupportingEvidence = supporting_evidence.some(
  e => e.claim && e.source_url
);

const hasContradictingEvidence = contradicting_evidence.some(
  e => e.claim && e.source_url
);

const hasSources = sources_used.some(
  source => source.url
);

const research_sufficient =
  hasSources &&
  (hasSupportingEvidence || hasContradictingEvidence);

return {
  json: {
    normalized_proposition: original.normalized_proposition,

    forecast_horizon: original.forecast_horizon,

    supporting_evidence,

    contradicting_evidence,

    key_uncertainties: original.key_uncertainties || [],

    sources_used,

    research_sufficient,

    research_gap: research_sufficient
      ? ''
      : 'No meaningful source-backed evidence was found after the additional research.',

    research_enhanced_by_gemini: true
  }
};

return {
  json: {
    output: "Sorry, something went wrong while processing your request. Please try again."
  }
};

return {
  json: {
    output: "No question or proposition was provided. Please try again."
  }
};
